def nacti_csv(cesta):
    """Nacte CSV se zahlavim a vrati seznam slovniku."""
    radky = []
    with open(cesta, encoding='utf-8', newline='') as f:
        hlavicka = f.readline().strip().split(',')
        for radek in f:
            hodnoty = radek.rstrip('\n').split(',')
            if len(hodnoty) != len(hlavicka):
                continue
            radky.append(dict(zip(hlavicka, hodnoty)))
    return radky
def seskup(polozky, klic):
    """Vrati slovnik seznamu seskupenych podle hodnoty klice."""
    vysledek = {}
    for p in polozky:
        k = p.get(klic)
        if k is None:
            continue
        vysledek.setdefault(k, []).append(p)
    return vysledek


def soucet_po(polozky, klic):
    return {k: sum(int(x['castka']) for x in v) for k, v in seskup(polozky, klic).items()}
class Zasobnik:
    def __init__(self):
        self._data = []

    def push(self, hodnota):
        self._data.append(hodnota)

    def pop(self):
        if not self._data:
            raise IndexError('zasobnik je prazdny')
        return self._data.pop()

    def peek(self):
        return self._data[-1] if self._data else None

    def __len__(self):
        return len(self._data)
def fibonacci(n, memo=None):
    """Iterativni vypocet n-teho clenu Fibonacciho posloupnosti."""
    if memo is None:
        memo = {0: 0, 1: 1}
    for i in range(2, n + 1):
        memo[i] = memo[i - 1] + memo[i - 2]
    return memo[n]


def delitele(cislo):
    return [d for d in range(1, cislo + 1) if cislo % d == 0]
def rozsah_dnu(od, do):
    """Vrati seznam datumu vcetne obou kraju."""
    from datetime import date, timedelta
    d = od
    out = []
    while d <= do:
        out.append(d)
        d = d + timedelta(days=1)
    return out


def pracovni_dny(datumy):
    return [d for d in datumy if d.weekday() < 5]
import json


def nacti_json(cesta, vychozi=None):
    try:
        with open(cesta, encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        return {} if vychozi is None else vychozi
    except json.JSONDecodeError as e:
        raise ValueError(f'neplatny JSON v {cesta}: {e}') from e


def uloz_json(cesta, data):
    with open(cesta, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2, sort_keys=True)
def okna(sekvence, velikost):
    """Generator posouvajicich se oken pevne velikosti."""
    for i in range(len(sekvence) - velikost + 1):
        yield sekvence[i:i + velikost]


def prumer_oken(sekvence, velikost):
    return [sum(w) / len(w) for w in okna(sekvence, velikost)]


def rozptyl(hodnoty):
    if len(hodnoty) < 2:
        return 0.0
    m = sum(hodnoty) / len(hodnoty)
    return sum((x - m) ** 2 for x in hodnoty) / (len(hodnoty) - 1)
def parsuj_velikost(text):
    """Prevede '1h05m', '45m', '2h' na sekundy."""
    text = text.strip().lower()
    hodin = 0
    minut = 0
    if 'h' in text:
        casti = text.split('h')
        hodin = int(casti[0]) if casti[0] else 0
        text = casti[1]
    if text.endswith('m'):
        minut = int(text[:-1]) if text[:-1] else 0
    return hodin * 3600 + minut * 60


def formatuj(sekundy):
    return f'{sekundy // 3600}h{(sekundy % 3600) // 60:02d}m'
def scitani_s_limitem(cisla, limit):
    """ Secte cisla, ale nikdy neprekroci limit; vraci (soucet, zbytek). """
    soucet = 0
    zbytek = []
    for c in cisla:
        if soucet + c <= limit:
            soucet += c
        else:
            zbytek.append(c)
    return soucet, zbytek


def bezpecne_deleni(a, b):
    if b == 0:
        return None
    return a / b
